html:
{% set p = get_invoice_parties(doc) %}
{% set s = p.seller %}
{% set b = p.buyer %}
{% set rate = p.vat_rate or 0 %}
{% set sgn = -1 if doc.is_return else 1 %}
{% set is_note = doc.is_return or doc.is_debit_note %}
{% if doc.is_return and p.is_b2b %}{% set title_en = "Credit Note for Tax Invoice" %}{% set title_ar = "إشعار دائن للفاتورة الضريبية" %}
{% elif doc.is_return %}{% set title_en = "Credit Note for Simplified Tax Invoice" %}{% set title_ar = "إشعار دائن للفاتورة الضريبية المبسطة" %}
{% elif doc.is_debit_note and p.is_b2b %}{% set title_en = "Debit Note for Tax Invoice" %}{% set title_ar = "إشعار مدين للفاتورة الضريبية" %}
{% elif doc.is_debit_note %}{% set title_en = "Debit Note for Simplified Tax Invoice" %}{% set title_ar = "إشعار مدين للفاتورة الضريبية المبسطة" %}
{% elif p.is_b2b %}{% set title_en = "Tax Invoice" %}{% set title_ar = "فاتورة ضريبية" %}
{% else %}{% set title_en = "Simplified Tax Invoice" %}{% set title_ar = "فاتورة ضريبية مبسطة" %}{% endif %}
{% macro money(v) %}{{ frappe.utils.fmt_money((v or 0) * sgn, currency=doc.currency) }}{% endmacro %}
{% macro party(x, label_en, label_ar) %}
<div class="party">
	<div class="party-h">{{ label_en }} | {{ label_ar }}</div>
	<div class="party-n">{{ x.name_ar or "" }}{% if x.name_ar and x.name %} - {% endif %}{{ x.name or "" }}</div>
	<table class="kv">
		<tr><td>VAT No. | الرقم الضريبي</td><td dir="ltr">{{ x.vat or "—" }}</td></tr>
		{% if x.cr %}<tr><td>CR No. | السجل التجاري</td><td dir="ltr">{{ x.cr }}</td></tr>{% endif %}
		<tr><td>Street | الشارع</td><td>{{ x.street or "—" }}</td></tr>
		<tr><td>District | الحي</td><td>{{ x.district or "—" }}</td></tr>
		<tr><td>City | المدينة</td><td>{{ x.city or "—" }}</td></tr>
		<tr><td>Building No. | رقم المبنى</td><td dir="ltr">{{ x.building_number or "—" }}</td></tr>
		<tr><td>Postal Code | الرمز البريدي</td><td dir="ltr">{{ x.postal_code or "—" }}</td></tr>
		{% if x.additional_number %}<tr><td>Additional No. | الرقم الإضافي</td><td dir="ltr">{{ x.additional_number }}</td></tr>{% endif %}
		<tr><td>Country | الدولة</td><td>{{ x.country or "Saudi Arabia" }}</td></tr>
	</table>
</div>
{% endmacro %}

<style>
	.inv { font-size: 11px; color: #111; }
	.inv h1 { text-align: center; font-size: 20px; margin: 0 0 2px; }
	.inv .meta { width: 100%; margin: 6px 0 10px; border-collapse: collapse; }
	.inv .meta td { padding: 3px 6px; border: 1px solid #bbb; }
	.inv .meta td.l { background: #f3f3f3; width: 22%; font-weight: bold; }
	.inv .parties { width: 100%; border-collapse: separate; border-spacing: 8px 0; margin: 0 -8px 10px; }
	.inv .parties > tbody > tr > td { width: 50%; vertical-align: top; padding: 0; }
	.inv .party { border: 1px solid #999; padding: 6px 8px; }
	.inv .party-h { font-weight: bold; background: #eee; margin: -6px -8px 5px; padding: 4px 8px; }
	.inv .party-n { font-weight: bold; margin-bottom: 4px; }
	.inv .kv { width: 100%; border-collapse: collapse; }
	.inv .kv td { padding: 1px 0; vertical-align: top; }
	.inv .kv td:first-child { width: 48%; color: #444; }
	.inv .items { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
	.inv .items th, .inv .items td { border: 1px solid #999; padding: 4px 5px; }
	.inv .items th { background: #eee; text-align: center; font-size: 10px; }
	.inv .items td.n { text-align: right; white-space: nowrap; }
	.inv .totals { width: 55%; margin-left: auto; border-collapse: collapse; }
	.inv .totals td { border: 1px solid #999; padding: 4px 6px; }
	.inv .totals td.n { text-align: right; white-space: nowrap; }
	.inv .totals tr.g td { font-weight: bold; background: #eee; font-size: 12px; }
	.inv .qr { text-align: center; margin-top: 12px; }
	.inv .warn { border: 2px solid #c00; color: #c00; padding: 6px 10px; margin-bottom: 10px; font-weight: bold; }
	.inv .warn ul { margin: 4px 0 0; font-weight: normal; }
</style>

<div class="inv">
	{% if p.problems %}
	<div class="warn">Legal data incomplete - do not issue / بيانات نظامية ناقصة
		<ul>{% for x in p.problems %}<li>{{ x }}</li>{% endfor %}</ul>
	</div>
	{% endif %}

	<h1>{{ title_ar }} &nbsp;|&nbsp; {{ title_en }}</h1>

	<table class="meta">
		<tr>
			<td class="l">Invoice No. | رقم الفاتورة</td><td dir="ltr">{{ doc.name }}</td>
			<td class="l">Issue Date | تاريخ الإصدار</td><td dir="ltr">{{ frappe.utils.formatdate(doc.posting_date) }} {{ (doc.posting_time|string).split(".")[0] if doc.posting_time else "" }}</td>
		</tr>
		<tr>
			<td class="l">Supply Date | تاريخ التوريد</td><td dir="ltr">{{ frappe.utils.formatdate(doc.posting_date) }}</td>
			<td class="l">Currency | العملة</td><td dir="ltr">{{ doc.currency }}</td>
		</tr>
		{% if doc.po_no %}<tr><td class="l">Order Ref. | مرجع الطلب</td><td dir="ltr" colspan="3">{{ doc.po_no }}</td></tr>{% endif %}
		{% if is_note %}
		<tr><td class="l">Original Invoice | الفاتورة الأصلية</td><td dir="ltr">{{ doc.return_against or "—" }}</td>
		<td class="l">Reason | سبب الإصدار</td><td>{{ doc.remarks if doc.remarks and doc.remarks != "No Remarks" else ("Sales return | مرتجع مبيعات" if doc.is_return else "Price adjustment | تعديل سعر") }}</td></tr>
		{% endif %}
	</table>

	<table class="parties"><tbody><tr>
		<td>{{ party(s, "Seller", "البائع") }}</td>
		<td>
			{% if p.is_b2b %}
				{{ party(b, "Buyer", "المشتري") }}
			{% else %}
				<div class="party"><div class="party-h">Buyer | المشتري</div>
					<div class="party-n">{{ b.name or "" }}</div>
					{% if b.street or b.city %}<div>{{ b.street or "" }} {{ b.city or "" }}</div>{% endif %}
				</div>
			{% endif %}
		</td>
	</tr></tbody></table>

	<table class="items">
		<thead><tr>
			<th>#</th>
			<th>Description<br>الوصف</th>
			<th>Qty<br>الكمية</th>
			<th>Unit Price<br>سعر الوحدة</th>
			<th>Taxable Amount<br>المبلغ الخاضع</th>
			<th>VAT %<br>الضريبة %</th>
			<th>VAT Amount<br>مبلغ الضريبة</th>
			<th>Total (incl. VAT)<br>الإجمالي شامل الضريبة</th>
		</tr></thead>
		<tbody>
		{% for row in doc.items %}
			{% set vat = (row.net_amount or 0) * rate / 100 %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ row.item_name or row.item_code }}{% if row.description and row.description != row.item_name %}<br><small>{{ row.description|striptags|truncate(120) }}</small>{% endif %}</td>
				<td class="n">{{ "%g"|format((row.qty or 0) * sgn) }} {{ row.uom or "" }}</td>
				<td class="n">{{ frappe.utils.fmt_money(row.net_rate|abs, currency=doc.currency) }}</td>
				<td class="n">{{ money(row.net_amount) }}</td>
				<td class="n">{{ rate|round(2) }}%</td>
				<td class="n">{{ money(vat) }}</td>
				<td class="n">{{ money((row.net_amount or 0) + vat) }}</td>
			</tr>
		{% endfor %}
		</tbody>
	</table>

	<table class="totals">
		{% if doc.discount_amount %}<tr><td>Discount | الخصم</td><td class="n">{{ money(doc.discount_amount) }}</td></tr>{% endif %}
		<tr><td>Total excluding VAT | الإجمالي غير شامل الضريبة</td><td class="n">{{ money(doc.net_total) }}</td></tr>
		<tr><td>Total VAT | إجمالي ضريبة القيمة المضافة</td><td class="n">{{ money(doc.total_taxes_and_charges) }}</td></tr>
		<tr class="g"><td>Total incl. VAT | الإجمالي شامل الضريبة</td><td class="n">{{ money(doc.grand_total) }}</td></tr>
	</table>

	{% if doc.zatca_qr_base64 %}
	<div class="qr"><img src="{{ render_zatca_qr(doc.zatca_qr_base64) }}" style="width: 130px; height: 130px;"></div>
	{% endif %}
</div>
